package net.minecraft.world.entity.monster;import java.util.*;import net.minecraft.network.syncher.SynchedEntityData;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.resources.ResourceLocation;public class Zombie extends net.minecraft.world.entity.Entity {public static class Level {public boolean isClientSide;}public static class Point{public double x,y,z;public Point(double x,double y,double z){this.x=x;this.y=y;this.z=z;}}public static class Attr {public Map<ResourceLocation,AttributeModifier> mods=new HashMap<>();public void removeModifier(ResourceLocation id){mods.remove(id);}public void addTransientModifier(AttributeModifier m){mods.put(m.id(),m);}}public Level world=new Level();public SynchedEntityData data=new SynchedEntityData();public CompoundTag tag=new CompoundTag();public Attr speed=new Attr();public int tickCount,refresh;public boolean burning,hurtMarked,hasImpulse;public double pushX,pushZ;public int pushes;public void push(double x,double y,double z){pushX+=x;pushZ+=z;pushes++;}public Object level(){return world;}public SynchedEntityData getEntityData(){return data;}public CompoundTag getPersistentData(){return tag;}public float getMaxHealth(){return 20;}public float getBbHeight(){return 2;}public float getYRot(){return 0;}public Point position(){return new Point(0,0,0);}public void refreshDimensions(){refresh++;}public Attr getAttribute(Object holder){return speed;}public boolean isOnFire(){return burning;}}